package com.flippingmasterminds;

import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentMap;

public class BuyLimitPanel extends JPanel
{
    private BuyLimitTracker buyLimitTracker;
    private Map<Integer, ItemMeta> meta;

    private JPanel listPanel;
    private final Timer refreshTimer;

    private final ConcurrentMap<Integer, ImageIcon> imageCache;
    private final Set<Integer> loadingSet;
    private final ItemManager itemManager;
    private final ImageIcon placeholderIcon;

    private static final int ICON_SIZE = 32;
    private static final long FOUR_HOURS_MS = 4 * 60 * 60 * 1000L;

    public BuyLimitPanel(ConcurrentMap<Integer, ImageIcon> imageCache,
                         Set<Integer> loadingSet,
                         ItemManager itemManager,
                         ImageIcon placeholderIcon)
    {
        this.imageCache      = imageCache;
        this.loadingSet      = loadingSet;
        this.itemManager     = itemManager;
        this.placeholderIcon = placeholderIcon;

        setLayout(new BorderLayout());

        // Header
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

        JLabel title = new JLabel("⏱ Buy Limit Cooldowns");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        header.add(title);

        JLabel subtitle = new JLabel("Active 4-hour buy limit windows");
        subtitle.setFont(FontManager.getRunescapeSmallFont());
        subtitle.setForeground(Color.GRAY);
        subtitle.setAlignmentX(Component.LEFT_ALIGNMENT);
        header.add(subtitle);
        header.add(Box.createVerticalStrut(6));

        viewDropdown = new JComboBox<>(new ViewOption[]{CURRENT, ALL});
        viewDropdown.setToolTipText("Choose which account's buy limits to show");
        viewDropdown.setAlignmentX(Component.LEFT_ALIGNMENT);
        viewDropdown.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        viewDropdown.addActionListener(e ->
        {
            if (!updatingOptions) rebuildList();
        });
        header.add(viewDropdown);
        add(header, BorderLayout.NORTH);

        // Scrollable list
        listPanel = new JPanel();
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));

        JPanel wrapper = new JPanel(new BorderLayout());
        wrapper.add(listPanel, BorderLayout.NORTH);

        JScrollPane scroll = new JScrollPane(wrapper);
        scroll.setBorder(null);
        scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        JScrollBar vsb = scroll.getVerticalScrollBar();
        vsb.setPreferredSize(new Dimension(8, 0));
        vsb.setUnitIncrement(16);
        add(scroll, BorderLayout.CENTER);

        // Refresh every 30 seconds for accurate countdowns
        refreshTimer = new Timer(30_000, e -> rebuildList());
        refreshTimer.start();
    }

    public void stopTimer()
    {
        refreshTimer.stop();
    }

    public void setBuyLimitTracker(BuyLimitTracker tracker)
    {
        this.buyLimitTracker = tracker;
        rebuildList();
    }

    public void updateMeta(Map<Integer, ItemMeta> meta)
    {
        this.meta = meta;
        rebuildList();
    }

    void rebuildList()
    {
        listPanel.removeAll();
        pendingIcons.clear();

        if (buyLimitTracker == null)
        {
            addEmptyMessage("Tracker not ready.");
            listPanel.revalidate();
            listPanel.repaint();
            return;
        }

        List<BuyLimitTracker.AccountLimits> accounts = buyLimitTracker.getAllAccounts();
        updateViewOptions(accounts);
        ViewOption view = (ViewOption) viewDropdown.getSelectedItem();
        if (view == null) view = CURRENT;

        if (view == ALL)
        {
            boolean any = false;
            for (BuyLimitTracker.AccountLimits a : accounts)
            {
                if (a.limits.isEmpty()) continue;
                addAccountHeader(a.name + (a.current ? "  (this account)" : ""));
                addLimitRows(a.limits);
                any = true;
            }
            if (!any) addEmptyMessage("No active buy limits on any account.");
        }
        else
        {
            Map<Integer, Map<String, Object>> tracked = null;
            if (view == CURRENT)
            {
                tracked = buyLimitTracker.getAllTracked();
            }
            else
            {
                for (BuyLimitTracker.AccountLimits a : accounts)
                {
                    if (a.profileKey.equals(view.profileKey)) tracked = a.limits;
                }
            }

            if (tracked == null || tracked.isEmpty())
            {
                addEmptyMessage(view == CURRENT
                        ? "No active buy limits. Buy items on the GE to start tracking."
                        : "No active buy limits on this account.");
            }
            else
            {
                addLimitRows(tracked);
            }
        }

        listPanel.revalidate();
        listPanel.repaint();
    }

    /** Rows for one account, soonest reset first. */
    private void addLimitRows(Map<Integer, Map<String, Object>> tracked)
    {
        long now = System.currentTimeMillis();
        List<long[]> active = new ArrayList<>();
        for (Map.Entry<Integer, Map<String, Object>> entry : tracked.entrySet())
        {
            long firstBuy = (long) entry.getValue().get("firstBuyTimestamp");
            int  qty      = (int)  entry.getValue().get("quantityBought");
            long msLeft   = firstBuy + FOUR_HOURS_MS - now;
            if (msLeft > 0) active.add(new long[]{entry.getKey(), qty, msLeft});
        }
        active.sort((a, b) -> Long.compare(a[2], b[2]));

        for (long[] l : active)
        {
            listPanel.add(makeLimitRow((int) l[0], (int) l[1], l[2]));
            listPanel.add(Box.createVerticalStrut(4));
        }
        if (active.isEmpty()) addEmptyMessage("All buy limits have reset.");
    }

    private void addAccountHeader(String text)
    {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeBoldFont());
        label.setForeground(ColorScheme.BRAND_ORANGE);
        label.setBorder(BorderFactory.createEmptyBorder(8, 4, 4, 4));
        JPanel wrap = new JPanel(new BorderLayout());
        wrap.add(label, BorderLayout.WEST);
        wrap.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        listPanel.add(wrap);
    }

    // ── Account dropdown ─────────────────────────────────────────────────────

    private static class ViewOption
    {
        final String label;
        /** Profile key for a specific account; null for the fixed options. */
        final String profileKey;

        ViewOption(String label, String profileKey)
        {
            this.label      = label;
            this.profileKey = profileKey;
        }

        @Override
        public String toString()
        {
            return label;
        }
    }

    private static final ViewOption CURRENT = new ViewOption("Current account", null);
    private static final ViewOption ALL     = new ViewOption("All accounts", null);

    private final JComboBox<ViewOption> viewDropdown;
    private boolean updatingOptions;
    private List<String> optionSignature = new ArrayList<>();

    /** Keep one entry per known account, preserving the current selection. */
    private void updateViewOptions(List<BuyLimitTracker.AccountLimits> accounts)
    {
        List<String> signature = new ArrayList<>();
        for (BuyLimitTracker.AccountLimits a : accounts)
        {
            signature.add(a.profileKey + "|" + a.name);
        }
        if (signature.equals(optionSignature)) return;
        optionSignature = signature;

        ViewOption selected = (ViewOption) viewDropdown.getSelectedItem();
        updatingOptions = true;
        try
        {
            viewDropdown.removeAllItems();
            viewDropdown.addItem(CURRENT);
            viewDropdown.addItem(ALL);
            ViewOption reselect = selected == ALL ? ALL : CURRENT;
            for (BuyLimitTracker.AccountLimits a : accounts)
            {
                ViewOption opt = new ViewOption(a.name, a.profileKey);
                viewDropdown.addItem(opt);
                if (selected != null && a.profileKey.equals(selected.profileKey)) reselect = opt;
            }
            viewDropdown.setSelectedItem(reselect);
        }
        finally
        {
            updatingOptions = false;
        }
    }

    private JPanel makeLimitRow(int itemId, int qty, long msLeft)
    {
        long totalSeconds = msLeft / 1000;
        long hours   = totalSeconds / 3600;
        long minutes = (totalSeconds % 3600) / 60;
        long seconds = totalSeconds % 60;
        String timeStr = String.format("%dh %02dm %02ds", hours, minutes, seconds);

        // Progress bar value (0-100, how much time has passed)
        double progress = 1.0 - ((double) msLeft / FOUR_HOURS_MS);
        int progressPct = Math.min(100, Math.max(0, (int)(progress * 100)));

        String itemName = "Item " + itemId;
        if (meta != null && meta.containsKey(itemId))
        {
            itemName = meta.get(itemId).name;
        }

        JPanel row = new JPanel(new BorderLayout(8, 0))
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(ColorScheme.DARKER_GRAY_COLOR);
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
                g2.setColor(ColorScheme.DARK_GRAY_COLOR);
                g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 10, 10);
                g2.dispose();
            }
        };
        row.setOpaque(false);
        row.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 70));

        // Icon
        JLabel iconLbl = new JLabel();
        ImageIcon cached = imageCache.get(itemId);
        iconLbl.setIcon(cached != null ? cached : placeholderIcon);
        if (cached == null)
        {
            pendingIcons.watch(itemId, iconLbl);
            scheduleIconLoad(itemId);
        }
        row.add(iconLbl, BorderLayout.WEST);

        // Center text + progress bar
        JPanel center = new JPanel();
        center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
        center.setOpaque(false);

        String shortName = itemName.length() > 22 ? itemName.substring(0, 22) + "..." : itemName;
        JLabel nameLabel = new JLabel(shortName);
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(FontManager.getRunescapeBoldFont());
        nameLabel.setToolTipText(itemName);
        center.add(nameLabel);

        JLabel infoLabel = new JLabel(qty + " bought  ·  resets in " + timeStr);
        infoLabel.setFont(FontManager.getRunescapeSmallFont());
        infoLabel.setForeground(new Color(150, 160, 190));
        center.add(infoLabel);

        // Progress bar showing time elapsed
        JProgressBar bar = new JProgressBar(0, 100);
        bar.setValue(progressPct);
        bar.setStringPainted(false);
        bar.setPreferredSize(new Dimension(0, 6));
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 6));
        bar.setForeground(new Color(80, 120, 200));
        bar.setBackground(ColorScheme.DARK_GRAY_COLOR);
        bar.setBorderPainted(false);
        center.add(Box.createVerticalStrut(3));
        center.add(bar);

        row.add(center, BorderLayout.CENTER);

        return row;
    }

    private void addEmptyMessage(String text)
    {
        JPanel empty = new JPanel(new GridBagLayout());
        empty.setBorder(BorderFactory.createEmptyBorder(30, 10, 30, 10));
        // HTML with a fixed width lets longer messages wrap instead of running off the panel.
        JLabel emptyLabel = new JLabel("<html><div style='text-align:center;width:150px'>" + text + "</div></html>");
        emptyLabel.setForeground(Color.GRAY);
        empty.add(emptyLabel);
        listPanel.add(empty);
    }

    private final PendingIcons pendingIcons = new PendingIcons();

    private void scheduleIconLoad(int itemId)
    {
        FlippingMastermindsPanel.loadIconAsync(itemId, ICON_SIZE,
                imageCache, loadingSet, itemManager, () -> pendingIcons.apply(imageCache));
    }

}

package com.flippingmasterminds;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * Tracks the GE's 4-hour buy limit windows, per account (RS profile).
 * A window starts at an item's first buy and resets four hours later.
 * Thread-safe: called from the client thread, the scheduler and the Swing thread.
 */
public class BuyLimitTracker
{
    private static final long FOUR_HOURS_MS = 4 * 60 * 60 * 1000L;

    private final ConfigManager configManager;
    private final Map<Integer, BuyRecord> records = new HashMap<>();

    public BuyLimitTracker(ConfigManager configManager)
    {
        this.configManager = configManager;
        reload();
    }

    public synchronized void recordBuy(int itemId, int quantity)
    {
        BuyRecord record = records.get(itemId);

        if (record == null || record.isExpired())
        {
            record = new BuyRecord(System.currentTimeMillis(), quantity);
            records.put(itemId, record);
        }
        else
        {
            record.addQuantity(quantity);
        }

        save();
    }

    public synchronized Map<Integer, Map<String, Object>> getAllTracked()
    {
        Map<Integer, Map<String, Object>> trackedData = new HashMap<>();

        Iterator<Map.Entry<Integer, BuyRecord>> iterator = records.entrySet().iterator();
        boolean removedAny = false;

        while (iterator.hasNext())
        {
            Map.Entry<Integer, BuyRecord> entry = iterator.next();
            BuyRecord record = entry.getValue();

            if (record.isExpired())
            {
                iterator.remove();
                removedAny = true;
            }
            else
            {
                Map<String, Object> itemData = new HashMap<>();
                itemData.put("firstBuyTimestamp", record.getFirstBuyTimestamp());
                itemData.put("quantityBought", record.getQuantityBought());
                trackedData.put(entry.getKey(), itemData);
            }
        }

        if (removedAny)
        {
            save();
        }

        return trackedData;
    }

    private static final String CONFIG_GROUP = "flippingmasterminds";
    private static final String CONFIG_KEY   = "buyLimitRecords";

    /** Reload for the current RuneScape profile (account). */
    public synchronized void reload()
    {
        records.clear();
        load();
        slots.clear();
        slots.putAll(parseSlots(configManager.getRSProfileKey() == null ? null
                : configManager.getRSProfileConfiguration(CONFIG_GROUP, SLOTS_KEY)));
    }

    // ── Offer slots ──────────────────────────────────────────────────────────
    // The last seen fill of each slot is saved per account, so fills that happen
    // while logged out are counted on the next login, and nothing is counted twice.

    private static final String SLOTS_KEY = "buyLimitSlots";
    /** Slot index to {itemId, quantitySold} last seen, for buy offers only. */
    private final Map<Integer, int[]> slots = new HashMap<>();

    /**
     * Count newly filled buy quantity for an offer update.
     *
     * @param settling true while the client replays offer states after login, when EMPTY
     *                 events are not real (they arrive before each slot's actual state)
     */
    public synchronized void onOfferUpdate(int slot, int itemId, int quantitySold, boolean buy,
                                           boolean empty, boolean settling)
    {
        if (empty || !buy)
        {
            // Only buy offers count towards limits. Login replays EMPTY before each slot's
            // real state, so an EMPTY then must not wipe the saved fill.
            if ((!empty || !settling) && slots.remove(slot) != null) saveSlots();
            return;
        }

        int[] last = slots.get(slot);
        // During the login replay with nothing saved for the slot (e.g. first run), we can't
        // tell when it filled, so just remember where it is now instead of counting it.
        int delta = last == null && settling ? 0 : newlyFilled(last, itemId, quantitySold);
        if (delta > 0) recordBuy(itemId, delta);

        if (last == null || last[0] != itemId || last[1] != quantitySold)
        {
            slots.put(slot, new int[]{itemId, quantitySold});
            saveSlots();
        }
    }

    /**
     * Quantity filled since the slot was last seen. It's the same offer if the item matches
     * and the fill hasn't gone backwards; otherwise it's a new offer and all of it is new.
     *
     * @param last {itemId, quantitySold} last seen for the slot, or null
     */
    static int newlyFilled(int[] last, int itemId, int quantitySold)
    {
        boolean sameOffer = last != null && last[0] == itemId && quantitySold >= last[1];
        return sameOffer ? quantitySold - last[1] : quantitySold;
    }

    static Map<Integer, int[]> parseSlots(String raw)
    {
        Map<Integer, int[]> out = new HashMap<>();
        if (raw == null || raw.isEmpty()) return out;
        for (String entry : raw.split(";"))
        {
            String[] p = entry.split(",");
            if (p.length != 3) continue;
            try
            {
                out.put(Integer.parseInt(p[0]), new int[]{Integer.parseInt(p[1]), Integer.parseInt(p[2])});
            }
            catch (NumberFormatException ignored) {}
        }
        return out;
    }

    private void saveSlots()
    {
        if (configManager.getRSProfileKey() == null) return;
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, int[]> e : slots.entrySet())
        {
            if (sb.length() > 0) sb.append(';');
            sb.append(e.getKey()).append(',').append(e.getValue()[0]).append(',').append(e.getValue()[1]);
        }
        configManager.setRSProfileConfiguration(CONFIG_GROUP, SLOTS_KEY, sb.toString());
    }

    /**
     * Buy limits are per account, so they are stored in the RS profile config.
     * Older versions stored one shared list; it is moved to the first account that loads.
     */
    private void load()
    {
        if (configManager.getRSProfileKey() == null) return;

        String raw = configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY);
        boolean migrating = false;
        if (raw == null)
        {
            raw = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY);
            migrating = raw != null;
        }
        records.putAll(parse(raw));
        if (migrating)
        {
            save();
            configManager.unsetConfiguration(CONFIG_GROUP, CONFIG_KEY);
        }
    }

    /** Active (unexpired) records from a saved "itemId,firstBuyTimestamp,quantity;..." string. */
    private static Map<Integer, BuyRecord> parse(String raw)
    {
        Map<Integer, BuyRecord> parsed = new HashMap<>();
        if (raw == null || raw.isEmpty()) return parsed;

        for (String entry : raw.split(";"))
        {
            String[] parts = entry.split(",");
            if (parts.length != 3) continue;
            try
            {
                int  itemId    = Integer.parseInt(parts[0]);
                long timestamp = Long.parseLong(parts[1]);
                int  qty       = Integer.parseInt(parts[2]);
                BuyRecord record = new BuyRecord(timestamp, qty);
                if (!record.isExpired())
                {
                    parsed.put(itemId, record);
                }
            }
            catch (NumberFormatException ignored) {}
        }
        return parsed;
    }

    // ── All accounts ─────────────────────────────────────────────────────────

    public static class AccountLimits
    {
        public final String profileKey;
        public final String name;
        public final boolean current;
        /** Same shape as {@link #getAllTracked()}. */
        public final Map<Integer, Map<String, Object>> limits;

        AccountLimits(String profileKey, String name, boolean current, Map<Integer, Map<String, Object>> limits)
        {
            this.profileKey = profileKey;
            this.name       = name;
            this.current    = current;
            this.limits     = limits;
        }
    }

    /** Active buy limits for every account RuneLite has a profile for, current account first. */
    public synchronized List<AccountLimits> getAllAccounts()
    {
        List<AccountLimits> out = new ArrayList<>();
        String currentKey = configManager.getRSProfileKey();
        boolean foundCurrent = false;

        for (RuneScapeProfile p : configManager.getRSProfiles())
        {
            boolean current = p.getKey().equals(currentKey);
            foundCurrent |= current;
            Map<Integer, Map<String, Object>> limits = current
                    ? getAllTracked()
                    : toTracked(parse(configManager.getConfiguration(CONFIG_GROUP, p.getKey(), CONFIG_KEY)));
            AccountLimits a = new AccountLimits(p.getKey(), profileName(p), current, limits);
            if (current) out.add(0, a);
            else out.add(a);
        }

        if (!foundCurrent && currentKey != null)
        {
            out.add(0, new AccountLimits(currentKey, "Current account", true, getAllTracked()));
        }
        return out;
    }

    private static String profileName(RuneScapeProfile p)
    {
        String name = p.getDisplayName() == null || p.getDisplayName().isEmpty()
                ? "Unknown account" : p.getDisplayName();
        if (p.getType() != null && p.getType() != RuneScapeProfileType.STANDARD)
        {
            String type = p.getType().name().toLowerCase().replace('_', ' ');
            name += " (" + Character.toUpperCase(type.charAt(0)) + type.substring(1) + ")";
        }
        return name;
    }

    private static Map<Integer, Map<String, Object>> toTracked(Map<Integer, BuyRecord> recs)
    {
        Map<Integer, Map<String, Object>> out = new HashMap<>();
        for (Map.Entry<Integer, BuyRecord> e : recs.entrySet())
        {
            Map<String, Object> itemData = new HashMap<>();
            itemData.put("firstBuyTimestamp", e.getValue().getFirstBuyTimestamp());
            itemData.put("quantityBought", e.getValue().getQuantityBought());
            out.put(e.getKey(), itemData);
        }
        return out;
    }

    private void save()
    {
        if (configManager.getRSProfileKey() == null) return;

        StringBuilder sb = new StringBuilder();
        for (Map.Entry<Integer, BuyRecord> entry : records.entrySet())
        {
            BuyRecord r = entry.getValue();
            if (r.isExpired()) continue;
            if (sb.length() > 0) sb.append(';');
            sb.append(entry.getKey()).append(',')
              .append(r.getFirstBuyTimestamp()).append(',')
              .append(r.getQuantityBought());
        }
        configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY, sb.toString());
    }

    private static class BuyRecord
    {
        private final long firstBuyTimestamp;
        private int quantityBought;

        public BuyRecord(long firstBuyTimestamp, int quantityBought)
        {
            this.firstBuyTimestamp = firstBuyTimestamp;
            this.quantityBought = quantityBought;
        }

        public long getFirstBuyTimestamp()
        {
            return firstBuyTimestamp;
        }

        public int getQuantityBought()
        {
            return quantityBought;
        }

        public void addQuantity(int quantity)
        {
            this.quantityBought += quantity;
        }

        public boolean isExpired()
        {
            return System.currentTimeMillis() - firstBuyTimestamp > FOUR_HOURS_MS;
        }
    }
}

package com.flippingmasterminds;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("flippingmasterminds")
public interface FlippingMastermindsConfig extends Config
{
	// ── Sections ──────────────────────────────────────────────────────────────

	@ConfigSection(
			name = "Account",
			description = "Connect the plugin to your Flipping Masterminds account",
			position = 0
	)
	String accountSection = "account";

	@ConfigSection(
			name = "Market Panel",
			description = "The side panel showing price movers, alerts and buy limits",
			position = 1
	)
	String marketSection = "market";

	@ConfigSection(
			name = "Grand Exchange",
			description = "Extra information shown on the Grand Exchange offer screens",
			position = 2
	)
	String geSection = "grandExchange";

	@ConfigSection(
			name = "GE Trade History",
			description = "Extended trade history, search and trade details in the GE history window",
			position = 3
	)
	String historySection = "tradeHistory";

	@ConfigSection(
			name = "Notifications",
			description = "Desktop notifications for price alerts and buy limit resets",
			position = 4
	)
	String notificationSection = "notifications";

	// ── Account ───────────────────────────────────────────────────────────────

	@ConfigItem(
			keyName = "apiToken",
			name = "API Token",
			description = "Run /generate_api_token in the Flipping Masterminds Discord to get your token. Join at discord.gg/VnsS2PP4Vt",
			position = 0,
			section = accountSection
	)
	default String apiToken()
	{
		return "";
	}

	// ── Market Panel ──────────────────────────────────────────────────────────

	@ConfigItem(
			keyName = "showVolume",
			name = "Show Volume",
			description = "Display the number of items traded in the last 24 hours on each item row",
			position = 0,
			section = marketSection
	)
	default boolean showVolume()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showPrices",
			name = "Show Prices",
			description = "Display the historical (snapshot) price and current (latest) price on each item row",
			position = 1,
			section = marketSection
	)
	default boolean showPrices()
	{
		return true;
	}

	@ConfigItem(
			keyName = "autoRefresh",
			name = "Auto Refresh Prices",
			description = "Automatically fetch the latest prices on a timer (needed for price alerts to trigger)",
			position = 2,
			section = marketSection
	)
	default boolean autoRefresh()
	{
		return true;
	}

