	@Subscribe
	public void onClientTick(ClientTick event)
	{
		GeHistoryExtender h = geHistory;
		if (h != null && config.extendedGeHistory()) h.tick();

		GeOfferValueExpander v = offerValues;
		if (v != null) v.tick();
	}

