    // ── Search ───────────────────────────────────────────────────────────────

    private void onSearchChanged()
    {
        if (suppressSearchListener) return;

        String query = searchField.getText().trim().toLowerCase();

        if (selectedItemId > 0 && !selectedItemName.equalsIgnoreCase(query))
        {
            selectedItemId = -1;
            selectedItemName = "";
        }

        updateAddButton();
        searchResultsPanel.removeAll();

        if (query.length() < 2 || meta == null)
        {
            searchResultsPanel.setVisible(false);
            searchResultsPanel.revalidate();
            return;
        }

        List<ItemMeta> matches = new ArrayList<>();
        for (ItemMeta im : meta.values())
        {
            if (im.name.toLowerCase().contains(query))
            {
                matches.add(im);
                if (matches.size() >= 8) break;
            }
        }

        if (matches.isEmpty())
        {
            searchResultsPanel.setVisible(false);
            searchResultsPanel.revalidate();
            return;
        }

        for (ItemMeta im : matches)
        {
            JPanel resultRow = new JPanel(new BorderLayout());
            resultRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
            resultRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

            String priceStr = "";
            if (currentPrices != null && currentPrices.containsKey(im.id))
            {
                priceStr = " (" + formatGp(currentPrices.get(im.id)) + ")";
            }
            JLabel nameLabel = new JLabel(im.name + priceStr);
            nameLabel.setFont(FontManager.getRunescapeSmallFont());
            resultRow.add(nameLabel, BorderLayout.CENTER);

            resultRow.addMouseListener(new MouseAdapter()
            {
                @Override
                public void mouseClicked(MouseEvent e)
                {
                    selectedItemId = im.id;
                    selectedItemName = im.name;
                    suppressSearchListener = true;
                    searchField.setText(im.name);
                    suppressSearchListener = false;
                    searchResultsPanel.setVisible(false);
                    searchResultsPanel.revalidate();
                    updateAddButton();
                }

                @Override
                public void mouseEntered(MouseEvent e)
                {
                    resultRow.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
                    resultRow.setOpaque(true);
                }

                @Override
                public void mouseExited(MouseEvent e)
                {
                    resultRow.setOpaque(false);
                }
            });

            searchResultsPanel.add(resultRow);
        }

        searchResultsPanel.setVisible(true);
        searchResultsPanel.revalidate();
        searchResultsPanel.repaint();
    }

    // ── Add button / price parsing ───────────────────────────────────────────

    private void updateAddButton()
    {
        boolean hasItem   = selectedItemId > 0;
        boolean hasPrice  = parseShorthandPrice(targetPriceField.getText()) > 0;
        boolean hasExpiry = parseDuration(expiresField.getText()) > 0;
        addButton.setEnabled(hasItem && hasPrice && hasExpiry);

        String searchText = searchField.getText().trim();
        searchField.setBorder(!searchText.isEmpty() && !hasItem ? invalidFieldBorder : defaultFieldBorder);

        String priceText = targetPriceField.getText().trim();
        targetPriceField.setBorder(!priceText.isEmpty() && !hasPrice ? invalidFieldBorder : defaultFieldBorder);

        String expiryText = expiresField.getText().trim();
        expiresField.setBorder(!expiryText.isEmpty() && !hasExpiry ? invalidFieldBorder : defaultFieldBorder);
    }

    private void onAddAlert()
    {
        if (tracker == null || selectedItemId <= 0) return;

        long targetPrice = parseShorthandPrice(targetPriceField.getText());
        if (targetPrice <= 0) return;

        long expiryMs = parseDuration(expiresField.getText());
        if (expiryMs <= 0) return;

        PriceAlertTracker.Direction dir =
                (PriceAlertTracker.Direction) directionDropdown.getSelectedItem();

        tracker.addAlert(selectedItemId, selectedItemName, targetPrice, dir, expiryMs);

        suppressSearchListener = true;
        searchField.setText("");
        suppressSearchListener = false;
        targetPriceField.setText("");
        expiresField.setText("24h");
        selectedItemId = -1;
        selectedItemName = "";
        addButton.setEnabled(false);

        rebuildAlertList();
    }

    // ── Discord command parser ───────────────────────────────────────────────

    private void onParseDiscordCommand()
    {
        String raw = discordCommandField.getText().trim();
        if (raw.isEmpty())
        {
            discordStatus.setText("Paste a /track_price command above.");
            discordStatus.setForeground(new Color(200, 100, 100));
            return;
        }

        // Strip leading slash-command name if present
        String cmd = raw.replaceFirst("^/track_price\\s*", "");

        Long price    = extractLong(cmd, "price");
        String movement = extractMovement(cmd);
        Integer itemId  = extractInt(cmd, "item_id");
        String itemName = extractString(cmd, "item_name");
        Long fsHours    = extractLong(cmd, "fs_hours");

        if (price == null || price <= 0)
        {
            discordStatus.setText("Missing or invalid price.");
            discordStatus.setForeground(new Color(200, 100, 100));
            return;
        }

        if (movement == null)
        {
            discordStatus.setText("Missing movement (Rises/Falls).");
            discordStatus.setForeground(new Color(200, 100, 100));
            return;
        }

        PriceAlertTracker.Direction dir = "falls".equals(movement)
                ? PriceAlertTracker.Direction.BELOW
                : PriceAlertTracker.Direction.ABOVE;

        long expiryMs = fsHours != null && fsHours > 0
                ? fsHours * 60 * 60 * 1000L
                : 30L * 24 * 60 * 60 * 1000L;

        // Resolve item
        int resolvedId = -1;
        String resolvedName = "";

        if (itemId != null && itemId > 0)
        {
            resolvedId = itemId;
            if (meta != null && meta.containsKey(itemId))
            {
                resolvedName = meta.get(itemId).name;
            }
            else
            {
                resolvedName = "Item " + itemId;
            }
        }
        else if (itemName != null && !itemName.isEmpty() && meta != null)
        {
            String lower = itemName.toLowerCase();
            ItemMeta bestMatch = null;
            for (ItemMeta im : meta.values())
            {
                if (im.name.equalsIgnoreCase(itemName))
                {
                    bestMatch = im;
                    break;
                }
                if (bestMatch == null && im.name.toLowerCase().contains(lower))
                {
                    bestMatch = im;
                }
            }
            if (bestMatch != null)
            {
                resolvedId = bestMatch.id;
                resolvedName = bestMatch.name;
            }
        }

        if (resolvedId <= 0)
        {
            discordStatus.setText("Unknown item: add item_id.");
            discordStatus.setForeground(new Color(200, 100, 100));
            return;
        }

        if (tracker == null)
        {
            discordStatus.setText("Tracker not ready.");
            discordStatus.setForeground(new Color(200, 100, 100));
            return;
        }

        tracker.addAlert(resolvedId, resolvedName, price, dir, expiryMs);
        discordCommandField.setText("");
        discordStatus.setText("Added: " + resolvedName + " " + (dir == PriceAlertTracker.Direction.BELOW ? "falls to" : "rises to") + " " + formatGp(price));
        discordStatus.setForeground(new Color(80, 200, 80));
        rebuildAlertList();
    }

    private static Long extractLong(String cmd, String key)
    {
        Matcher m = Pattern.compile(key + ":(\\d+)", Pattern.CASE_INSENSITIVE).matcher(cmd);
        if (m.find())
        {
            try { return Long.parseLong(m.group(1)); }
            catch (NumberFormatException e) { return null; }
        }
        return null;
    }

    private static Integer extractInt(String cmd, String key)
    {
        Long val = extractLong(cmd, key);
        return val != null ? val.intValue() : null;
    }

    private static String extractString(String cmd, String key)
    {
        Matcher m = Pattern.compile(key + ":([^\\s:]+(?:\\s+[^\\s:]+)*?)(?=\\s+\\w+:|$)",
                Pattern.CASE_INSENSITIVE).matcher(cmd);
        if (m.find()) return m.group(1).trim();
        return null;
    }

    private static String extractMovement(String cmd)
    {
        Matcher m = Pattern.compile("movement:(rises(?:\\s+to)?|falls(?:\\s+to)?)",
                Pattern.CASE_INSENSITIVE).matcher(cmd);
        if (m.find())
        {
            String val = m.group(1).toLowerCase();
            return val.startsWith("falls") ? "falls" : "rises";
        }
        return null;
    }

    static long parseShorthandPrice(String input)
    {
        if (input == null) return -1;
        String trimmed = input.trim();
        if (trimmed.isEmpty()) return -1;

        Matcher m = SHORTHAND_PATTERN.matcher(trimmed);
        if (!m.matches()) return -1;

        double num = Double.parseDouble(m.group(1));
        String suffix = m.group(2);

        if (suffix != null)
        {
            switch (suffix.toLowerCase())
            {
                case "k": num *= 1_000;         break;
                case "m": num *= 1_000_000;     break;
                case "b": num *= 1_000_000_000; break;
            }
        }

        return Math.round(num);
    }

    static long parseDuration(String input)
    {
        if (input == null) return -1;
        String trimmed = input.trim();
        if (trimmed.isEmpty()) return -1;

        Matcher m = DURATION_PATTERN.matcher(trimmed);
        if (!m.matches()) return -1;

        double num = Double.parseDouble(m.group(1));
        String unit = m.group(2).toLowerCase();

        switch (unit)
        {
            case "h": return Math.round(num * 60 * 60 * 1000L);
            case "d": return Math.round(num * 24 * 60 * 60 * 1000L);
            case "w": return Math.round(num * 7 * 24 * 60 * 60 * 1000L);
            default:  return -1;
        }
    }

    // ── Alert list ───────────────────────────────────────────────────────────

    void rebuildAlertList()
    {
        alertListPanel.removeAll();
        pendingIcons.clear();

        if (tracker == null || tracker.getAlerts().isEmpty())
        {
            JPanel empty = new JPanel(new GridBagLayout());
            JLabel emptyLabel = new JLabel("No price alerts set.");
            emptyLabel.setForeground(Color.GRAY);
            empty.add(emptyLabel);
            alertListPanel.add(empty);
        }
        else
        {
            List<PriceAlertTracker.PriceAlert> alerts = tracker.getAlerts();
            for (int i = 0; i < alerts.size(); i++)
            {
                alertListPanel.add(makeAlertRow(alerts.get(i), i));
                alertListPanel.add(Box.createVerticalStrut(4));
            }
        }

        // Alert history
        buildHistorySection();

        alertListPanel.revalidate();
        alertListPanel.repaint();
    }

    private JPanel makeAlertRow(PriceAlertTracker.PriceAlert alert, int index)
    {
        Color borderColor = alert.triggered ? TRIGGERED_BORDER
                          : alert.stale     ? STALE_BORDER
                          : ColorScheme.DARK_GRAY_COLOR;
        Color bgColor     = alert.triggered ? TRIGGERED_BG
                          : alert.stale     ? STALE_BG
                          : UNTRIGGERED_BG;

        JPanel row = new JPanel(new BorderLayout(6, 4))
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(getBackground());
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
                g2.setColor(borderColor);
                g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 10, 10);
                g2.dispose();
            }
        };
        row.setOpaque(false);
        row.setBackground(bgColor);
        row.setBorder(BorderFactory.createEmptyBorder(8, 10, 8, 10));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 90));

        // Item icon on the left
        JLabel iconLabel = new JLabel();
        ImageIcon cached = imageCache.get(alert.itemId);
        iconLabel.setIcon(cached != null ? cached : placeholderIcon);
        if (cached == null)
        {
            pendingIcons.watch(alert.itemId, iconLabel);
            scheduleIconLoad(alert.itemId);
        }
        row.add(iconLabel, BorderLayout.WEST);

        // Text in the center
        JPanel textPanel = new JPanel();
        textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
        textPanel.setOpaque(false);

        String name = alert.itemName;
        if (name.length() > 20) name = name.substring(0, 20) + "...";
        JLabel nameLabel = new JLabel(name);
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(FontManager.getRunescapeBoldFont());
        nameLabel.setToolTipText(alert.itemName);
        textPanel.add(nameLabel);

        // Direction line with graph emoji
        String dirEmoji = alert.direction == PriceAlertTracker.Direction.BELOW
                ? "📉 " : "📈 ";
        String dirText = alert.direction == PriceAlertTracker.Direction.BELOW
                ? "Below " : "Above ";
        JLabel condLabel = new JLabel(dirEmoji + dirText + formatGp(alert.targetPrice));
        condLabel.setForeground(alert.direction == PriceAlertTracker.Direction.BELOW
                ? new Color(220, 140, 140) : new Color(140, 200, 140));
        condLabel.setFont(FontManager.getRunescapeSmallFont());
        textPanel.add(condLabel);

        if (alert.triggered)
        {
            JLabel trigLabel = new JLabel("✅ Triggered at " + formatGp(alert.triggeredPrice));
            trigLabel.setForeground(new Color(80, 200, 80));
            trigLabel.setFont(FontManager.getRunescapeBoldFont());
            textPanel.add(trigLabel);
        }
        else if (alert.stale)
        {
            JLabel staleLabel = new JLabel("⚠ Expired after " + formatDuration(alert.expiryMs));
            staleLabel.setToolTipText("Never reached the target price within " + formatDuration(alert.expiryMs));
            staleLabel.setForeground(new Color(220, 170, 50));
            staleLabel.setFont(FontManager.getRunescapeBoldFont());
            textPanel.add(staleLabel);
        }
        else
        {
            long elapsed   = System.currentTimeMillis() - alert.createdAt;
            long daysActive = elapsed / (24 * 60 * 60 * 1000L);
            long msLeft     = alert.expiryMs - elapsed;
            long hoursLeft  = msLeft / (60 * 60 * 1000L);
            long minsLeft   = msLeft / (60 * 1000L);
            String ageText = daysActive == 0 ? "today" : daysActive + "d ago";
            String timeLeft;
            if (minsLeft <= 0)        timeLeft = "expiring soon";
            else if (minsLeft < 60)   timeLeft = minsLeft + "m left";
            else if (hoursLeft < 24)  timeLeft = hoursLeft + "h left";
            else                      timeLeft = (hoursLeft / 24) + "d left";

            if (currentPrices != null && currentPrices.containsKey(alert.itemId))
            {
                long cur = currentPrices.get(alert.itemId);
                JLabel curLabel = new JLabel("Now " + formatGp(cur) + " · " + timeLeft);
                curLabel.setToolTipText("Current price " + formatGp(cur) + ", set " + ageText + ", " + timeLeft);
                curLabel.setForeground(new Color(140, 140, 140));
                curLabel.setFont(FontManager.getRunescapeSmallFont());
                textPanel.add(curLabel);
            }
            else
            {
                JLabel ageLabel = new JLabel("Set " + ageText + " · " + timeLeft);
                ageLabel.setForeground(new Color(140, 140, 140));
                ageLabel.setFont(FontManager.getRunescapeSmallFont());
                textPanel.add(ageLabel);
            }
        }

        row.add(textPanel, BorderLayout.CENTER);

        // Remove button
        JButton removeBtn = new JButton("✖");
        removeBtn.setFocusPainted(false);
        removeBtn.setContentAreaFilled(false);
        removeBtn.setBorderPainted(false);
        removeBtn.setForeground(new Color(180, 80, 80));
        removeBtn.setToolTipText("Remove alert");
        removeBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        removeBtn.setPreferredSize(new Dimension(28, 28));
        removeBtn.addActionListener(e -> {
            tracker.removeAlert(index);
            rebuildAlertList();
        });
        row.add(removeBtn, BorderLayout.EAST);

        return row;
    }

    // ── Alert history section ───────────────────────────────────────────────

    private void buildHistorySection()
    {
        if (tracker == null) return;

        List<PriceAlertTracker.AlertHistoryEntry> hist = tracker.getHistory();
        if (hist.isEmpty()) return;

        alertListPanel.add(Box.createVerticalStrut(8));
        JLabel header = new JLabel("📜 Alert History");
        header.setFont(FontManager.getRunescapeBoldFont());
        header.setForeground(new Color(180, 180, 180));
        header.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 0));
        // Full-width row like the alert rows, so BoxLayout doesn't push a
        // left-aligned label out to the centre line.
        JPanel headerRow = new JPanel(new BorderLayout());
        headerRow.add(header, BorderLayout.WEST);
        headerRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, header.getPreferredSize().height));
        alertListPanel.add(headerRow);
        alertListPanel.add(Box.createVerticalStrut(4));

        for (int idx = 0; idx < hist.size(); idx++)
        {
            PriceAlertTracker.AlertHistoryEntry h = hist.get(idx);
            final int histIndex = idx;
            JPanel hRow = new JPanel(new BorderLayout(6, 0))
            {
                @Override
                protected void paintComponent(Graphics g)
                {
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                    g2.setColor(getBackground());
                    g2.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
                    g2.setColor(ColorScheme.DARK_GRAY_COLOR);
                    g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 10, 10);
                    g2.dispose();
                }
            };
            hRow.setOpaque(false);
            hRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            hRow.setBorder(BorderFactory.createEmptyBorder(6, 10, 6, 10));
            hRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 50));

            JLabel iconLbl = new JLabel();
            ImageIcon cached = imageCache.get(h.itemId);
            iconLbl.setIcon(cached != null ? cached : placeholderIcon);
            if (cached == null)
            {
                pendingIcons.watch(h.itemId, iconLbl);
                scheduleIconLoad(h.itemId);
            }
            hRow.add(iconLbl, BorderLayout.WEST);

            JPanel textPanel = new JPanel();
            textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
            textPanel.setOpaque(false);

            String shortName = h.itemName.length() > 20 ? h.itemName.substring(0, 20) + "..." : h.itemName;
            String dirText = h.direction == PriceAlertTracker.Direction.BELOW ? "Below " : "Above ";
            JLabel nameLine = new JLabel(shortName + " — " + dirText + formatGp(h.targetPrice));
            nameLine.setFont(FontManager.getRunescapeSmallFont());
            nameLine.setForeground(new Color(160, 160, 160));
            nameLine.setToolTipText(h.itemName);
            textPanel.add(nameLine);

            boolean triggered = "TRIGGERED".equals(h.outcome);
            String outcomeText = triggered
                    ? "✅ Hit " + formatGp(h.triggeredPrice)
                    : "⚠ Expired";
            long ago = (System.currentTimeMillis() - h.completedAt) / (60 * 60 * 1000L);
            String agoText = ago < 1 ? "just now" : ago < 24 ? ago + "h ago" : (ago / 24) + "d ago";
            JLabel outLine = new JLabel(outcomeText + "  ·  " + agoText);
            outLine.setFont(FontManager.getRunescapeSmallFont());
            outLine.setForeground(triggered ? new Color(80, 160, 80) : new Color(180, 140, 50));
            textPanel.add(outLine);

            hRow.add(textPanel, BorderLayout.CENTER);

            JButton removeBtn = new JButton("✖");
            removeBtn.setFocusPainted(false);
            removeBtn.setContentAreaFilled(false);
            removeBtn.setBorderPainted(false);
            removeBtn.setForeground(new Color(120, 80, 80));
            removeBtn.setToolTipText("Remove from history");
            removeBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            removeBtn.setPreferredSize(new Dimension(24, 24));
            removeBtn.addActionListener(e -> {
                tracker.removeHistoryEntry(histIndex);
                rebuildAlertList();
            });
            hRow.add(removeBtn, BorderLayout.EAST);

            alertListPanel.add(hRow);
            alertListPanel.add(Box.createVerticalStrut(3));
        }
    }

    // ── Image loading ────────────────────────────────────────────────────────

    private final PendingIcons pendingIcons = new PendingIcons();

    private void scheduleIconLoad(int itemId)
    {
        FlippingMastermindsPanel.loadIconAsync(itemId, ICON_SIZE,
                imageCache, loadingSet, itemManager, () -> pendingIcons.apply(imageCache));
    }

    // ── Formatting ───────────────────────────────────────────────────────────

    private static String formatGp(long gp)
    {
        return FlippingMastermindsPanel.formatGp(gp);
    }

    private static String formatDuration(long ms)
    {
        long hours = ms / (60 * 60 * 1000L);
        if (hours < 24)  return hours + "h";
        long days = hours / 24;
        if (days < 7)    return days + "d";
        long weeks = days / 7;
        return weeks + "w";
    }
}

package com.flippingmasterminds;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import net.runelite.client.config.ConfigManager;

import java.lang.reflect.Type;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;

public class PriceAlertTracker
{
    private static final String CONFIG_GROUP       = "flippingmasterminds";
    private static final String CONFIG_KEY         = "priceAlerts";
    private static final String HISTORY_CONFIG_KEY = "priceAlertHistory";
    private static final long DEFAULT_EXPIRY_MS    = 24L * 60 * 60 * 1000;
    private static final int MAX_HISTORY_ENTRIES   = 50;

    private final ConfigManager configManager;
    private final Gson gson;
    private final List<PriceAlert> alerts = new CopyOnWriteArrayList<>();
    private final List<AlertHistoryEntry> history = new CopyOnWriteArrayList<>();

    public PriceAlertTracker(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson          = gson;
        load();
        loadHistory();
    }

    public List<PriceAlert> getAlerts()
    {
        return Collections.unmodifiableList(alerts);
    }

    public List<AlertHistoryEntry> getHistory()
    {
        return Collections.unmodifiableList(history);
    }

    public void addAlert(int itemId, String itemName, long targetPrice, Direction direction,
                         long expiryMs)
    {
        alerts.add(new PriceAlert(itemId, itemName, targetPrice, direction,
                false, false, System.currentTimeMillis(), expiryMs));
        save();
    }

    public void removeAlert(int index)
    {
        if (index >= 0 && index < alerts.size())
        {
            alerts.remove(index);
            save();
        }
    }

    public static class CheckResult
    {
        public final List<PriceAlert> newlyTriggered;
        public final List<PriceAlert> newlyStale;

        CheckResult(List<PriceAlert> triggered, List<PriceAlert> stale)
        {
            this.newlyTriggered = triggered;
            this.newlyStale     = stale;
        }
    }

    public CheckResult checkPrices(Map<Integer, Long> currentPrices)
    {
        List<PriceAlert> newlyTriggered = new ArrayList<>();
        List<PriceAlert> newlyStale     = new ArrayList<>();
        long now = System.currentTimeMillis();

        for (PriceAlert alert : alerts)
        {
            if (alert.triggered || alert.stale) continue;

            Long currentPrice = currentPrices.get(alert.itemId);
            if (currentPrice == null) continue;

            boolean met = false;
            if (alert.direction == Direction.BELOW && currentPrice <= alert.targetPrice)
                met = true;
            else if (alert.direction == Direction.ABOVE && currentPrice >= alert.targetPrice)
                met = true;

            if (met)
            {
                alert.triggered = true;
                alert.triggeredPrice = currentPrice;
                newlyTriggered.add(alert);
                recordHistory(alert, now, currentPrice, "TRIGGERED");
            }
            else if (now - alert.createdAt >= alert.expiryMs)
            {
                alert.stale = true;
                newlyStale.add(alert);
                recordHistory(alert, now, 0, "EXPIRED");
            }
        }

        boolean changed = !newlyTriggered.isEmpty() || !newlyStale.isEmpty();
        if (changed) save();
        return new CheckResult(newlyTriggered, newlyStale);
    }

    /** Whether any alert is still waiting to trigger or expire. */
    public boolean hasActiveAlerts()
    {
        for (PriceAlert a : alerts)
        {
            if (!a.triggered && !a.stale) return true;
        }
        return false;
    }

    public void clearCompleted()
    {
        alerts.removeIf(a -> a.triggered || a.stale);
        save();
    }

    public void removeHistoryEntry(int index)
    {
        if (index >= 0 && index < history.size())
        {
            history.remove(index);
            saveHistory();
        }
    }

    public void clearHistory()
    {
        history.clear();
        saveHistory();
    }

    private void recordHistory(PriceAlert alert, long completedAt, long trigPrice, String outcome)
    {
        history.add(0, new AlertHistoryEntry(
                alert.itemId, alert.itemName, alert.targetPrice,
                alert.direction, alert.createdAt, completedAt, trigPrice, outcome));

        while (history.size() > MAX_HISTORY_ENTRIES)
        {
            history.remove(history.size() - 1);
        }
        saveHistory();
    }

    // ── Alert persistence ───────────────────────────────────────────────────
    // Stored as JSON. Older versions used a hand-escaped "a,b,c|a,b,c" format,
    // which is still read once and re-saved as JSON.

    private static final Type ALERT_LIST    = new TypeToken<List<PriceAlert>>() {}.getType();
    private static final Type HISTORY_LIST  = new TypeToken<List<AlertHistoryEntry>>() {}.getType();

    private void load()
    {
        String raw = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY);
        List<PriceAlert> loaded = parseAlerts(raw, gson);
        alerts.addAll(loaded);
        if (raw != null && !raw.isEmpty() && !isJson(raw)) save();
    }

    static boolean isJson(String raw)
    {
        return raw.trim().startsWith("[");
    }

    static List<PriceAlert> parseAlerts(String raw, Gson gson)
    {
        List<PriceAlert> out = new ArrayList<>();
        if (raw == null || raw.isEmpty()) return out;

        if (isJson(raw))
        {
            try
            {
                List<PriceAlert> parsed = gson.fromJson(raw, ALERT_LIST);
                if (parsed != null)
                {
                    for (PriceAlert a : parsed)
                    {
                        if (a != null && a.itemName != null && a.direction != null) out.add(a);
                    }
                }
            }
            catch (Exception ignored) {}
            return out;
        }

        for (String entry : raw.split("\\|"))
        {
            String[] parts = entry.split(",", 10);
            if (parts.length < 5) continue;
            try
            {
                int       itemId      = Integer.parseInt(parts[0]);
                String    itemName    = parts[1].replace("&pipe;", "|").replace("&comma;", ",");
                long      target      = Long.parseLong(parts[2]);
                Direction dir         = Direction.valueOf(parts[3]);
                boolean   triggered   = Boolean.parseBoolean(parts[4]);
                long      trigPrice   = parts.length >= 6 ? Long.parseLong(parts[5]) : 0;
                long      created     = parts.length >= 7 ? Long.parseLong(parts[6]) : System.currentTimeMillis();
                boolean   stale       = parts.length >= 8 && Boolean.parseBoolean(parts[7]);
                long      expiryMs    = parts.length >= 9 ? Long.parseLong(parts[8]) : DEFAULT_EXPIRY_MS;

                PriceAlert alert = new PriceAlert(itemId, itemName, target, dir, triggered, stale, created, expiryMs);
                alert.triggeredPrice = trigPrice;
                out.add(alert);
            }
            catch (Exception ignored) {}
        }
        return out;
    }

    private void save()
    {
        configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY, gson.toJson(new ArrayList<>(alerts), ALERT_LIST));
    }

    // ── History persistence ─────────────────────────────────────────────────

    private void loadHistory()
    {
        String raw = configManager.getConfiguration(CONFIG_GROUP, HISTORY_CONFIG_KEY);
        history.addAll(parseHistory(raw, gson));
        if (raw != null && !raw.isEmpty() && !isJson(raw)) saveHistory();
    }

    static List<AlertHistoryEntry> parseHistory(String raw, Gson gson)
    {
        List<AlertHistoryEntry> out = new ArrayList<>();
        if (raw == null || raw.isEmpty()) return out;

        if (isJson(raw))
        {
            try
            {
                List<AlertHistoryEntry> parsed = gson.fromJson(raw, HISTORY_LIST);
                if (parsed != null)
                {
                    for (AlertHistoryEntry h : parsed)
                    {
                        if (h != null && h.itemName != null && h.direction != null) out.add(h);
                    }
                }
            }
            catch (Exception ignored) {}
            return out;
        }

        for (String entry : raw.split("\\|"))
        {
            String[] parts = entry.split(",", 8);
            if (parts.length < 8) continue;
            try
            {
                int       itemId      = Integer.parseInt(parts[0]);
                String    itemName    = parts[1].replace("&pipe;", "|").replace("&comma;", ",");
                long      target      = Long.parseLong(parts[2]);
                Direction dir         = Direction.valueOf(parts[3]);
                long      created     = Long.parseLong(parts[4]);
                long      completed   = Long.parseLong(parts[5]);
                long      trigPrice   = Long.parseLong(parts[6]);
                String    outcome     = parts[7];

                out.add(new AlertHistoryEntry(itemId, itemName, target, dir,
                        created, completed, trigPrice, outcome));
            }
            catch (Exception ignored) {}
        }
        return out;
    }

    private void saveHistory()
    {
        configManager.setConfiguration(CONFIG_GROUP, HISTORY_CONFIG_KEY, gson.toJson(new ArrayList<>(history), HISTORY_LIST));
    }

    // ── Types ───────────────────────────────────────────────────────────────

    public enum Direction
    {
        BELOW("Falls to or below"),
        ABOVE("Rises to or above");

        public final String label;

        Direction(String label) { this.label = label; }

        @Override
        public String toString() { return label; }
    }

    public static class PriceAlert
    {
        public final int       itemId;
        public final String    itemName;
        public final long      targetPrice;
        public final Direction direction;
        public final long      expiryMs;
        public long            createdAt;
        public boolean         triggered;
        public boolean         stale;
        public long            triggeredPrice;

        PriceAlert(int itemId, String itemName, long targetPrice, Direction direction,
                   boolean triggered, boolean stale, long createdAt, long expiryMs)
        {
            this.itemId      = itemId;
            this.itemName    = itemName;
            this.targetPrice = targetPrice;
            this.direction   = direction;
            this.triggered   = triggered;
            this.stale       = stale;
            this.createdAt   = createdAt;
            this.expiryMs    = expiryMs;
        }
    }

    public static class AlertHistoryEntry
    {
        public final int       itemId;
        public final String    itemName;
        public final long      targetPrice;
        public final Direction direction;
        public final long      createdAt;
        public final long      completedAt;
        public final long      triggeredPrice;
        public final String    outcome;

        AlertHistoryEntry(int itemId, String itemName, long targetPrice, Direction direction,
                          long createdAt, long completedAt, long triggeredPrice, String outcome)
        {
            this.itemId         = itemId;
            this.itemName       = itemName;
            this.targetPrice    = targetPrice;
            this.direction      = direction;
            this.createdAt      = createdAt;
            this.completedAt    = completedAt;
            this.triggeredPrice = triggeredPrice;
            this.outcome        = outcome;
        }
    }
}

package com.flippingmasterminds;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

import java.io.IOException;
import java.io.Reader;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

@Slf4j
class PriceDataFetcher
{
	private static final String LATEST_URL = "https://prices.runescape.wiki/api/v2/osrs/latest";
	private static final String MAPPING_URL = "https://prices.runescape.wiki/api/v1/osrs/mapping";
	private static final String LATEST_24H_URL = "https://prices.runescape.wiki/api/v2/osrs/24h";
	private static final String USER_AGENT = "Flipping Masterminds RuneLite plugin - Discord: Lindor";

	/** Historical snapshots only move hourly; item names rarely change. */
	private static final long SNAPSHOT_TTL_MS = 60 * 60 * 1000L;
	private static final long META_TTL_MS     = 24 * 60 * 60 * 1000L;

	private final OkHttpClient httpClient;
	private final Gson gson;

	// Cached between refreshes; only touched from the single fetch thread.
	private PriceAndVolume day, week, month, year;
	private long snapshotsFetchedAt;
	private Map<Integer, ItemMeta> meta;
	private long metaFetchedAt;

	PriceDataFetcher(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	FetchResult fetchAll() throws IOException
	{
		LatestPriceResult latestResult = fetchLatestPrices(LATEST_URL);

		long nowMs = System.currentTimeMillis();
		if (day == null || nowMs - snapshotsFetchedAt >= SNAPSHOT_TTL_MS)
		{
			long now = Instant.now().getEpochSecond();
			PriceAndVolume d = fetchPricesAndVolume(makeUrl1h(now, 86_400));
			PriceAndVolume w = fetchPricesAndVolume(makeUrl1h(now, 604_800));
			PriceAndVolume m = fetchPricesAndVolume(makeUrl24h(now, 2_629_743));
			PriceAndVolume y = fetchPricesAndVolume(makeUrl24h(now, 31_556_926));
			// The snapshots above only cover a single bucket at the start of each window,
			// so every range uses the trailing 24h volume instead.
			Map<Integer, Long> dailyVolume = fetchPricesAndVolume(LATEST_24H_URL).volume;
			day   = new PriceAndVolume(d.prices, dailyVolume);
			week  = new PriceAndVolume(w.prices, dailyVolume);
			month = new PriceAndVolume(m.prices, dailyVolume);
			year  = new PriceAndVolume(y.prices, dailyVolume);
			snapshotsFetchedAt = nowMs;
		}

		if (meta == null || nowMs - metaFetchedAt >= META_TTL_MS)
		{
			meta = fetchItemMeta(MAPPING_URL);
			metaFetchedAt = nowMs;
		}

		return new FetchResult(latestResult, day, week, month, year, meta);
	}

	LatestPriceResult fetchLatestPrices(String urlStr) throws IOException
	{
		Request request = new Request.Builder()
				.url(urlStr)
				.header("User-Agent", USER_AGENT)
				.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				throw new IOException("Failed to fetch latest prices: " + response.code());
			}

			try (Reader reader = response.body().charStream())
			{
				Map<Integer, Long> map    = new HashMap<>();
				Map<Integer, Long> high   = new HashMap<>();
				Map<Integer, Long> low    = new HashMap<>();
				JsonObject root = gson.fromJson(reader, JsonObject.class);
				JsonObject data = root.getAsJsonObject("data");

				for (String key : data.keySet())
				{
					try
					{
						int id  = Integer.parseInt(key);
						JsonObject obj = data.getAsJsonObject(key);
						if (obj.has("high") && obj.has("low")
								&& !obj.get("high").isJsonNull()
								&& !obj.get("low").isJsonNull())
						{
							long h = obj.get("high").getAsLong();
							long l = obj.get("low").getAsLong();
							map.put(id, (h + l) / 2);
							high.put(id, h);
							low.put(id, l);
						}
					}
					catch (Exception e)
					{
						log.debug("Skipping item {} in latest prices: {}", key, e.getMessage());
					}
				}

				return new LatestPriceResult(map, high, low);
			}
		}
	}

	PriceAndVolume fetchPricesAndVolume(String urlStr) throws IOException
	{
		Request request = new Request.Builder()
				.url(urlStr)
				.header("User-Agent", USER_AGENT)
				.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				throw new IOException("Failed to fetch prices: " + response.code());
			}

			try (Reader reader = response.body().charStream())
			{
				Map<Integer, Long> prices = new HashMap<>();
				Map<Integer, Long> volume = new HashMap<>();
				JsonObject root = gson.fromJson(reader, JsonObject.class);
				JsonObject data = root.getAsJsonObject("data");

				for (String key : data.keySet())
				{
					try
					{
						int id  = Integer.parseInt(key);
						JsonObject obj = data.getAsJsonObject(key);

						if (obj.has("avgHighPrice") && obj.has("avgLowPrice")
								&& !obj.get("avgHighPrice").isJsonNull()
								&& !obj.get("avgLowPrice").isJsonNull())
						{
							double h = obj.get("avgHighPrice").getAsDouble();
							double l = obj.get("avgLowPrice").getAsDouble();
							prices.put(id, Math.round((h + l) / 2.0));
						}

						long vol = 0;
						if (obj.has("highPriceVolume") && !obj.get("highPriceVolume").isJsonNull())
						{
							vol += obj.get("highPriceVolume").getAsLong();
						}
						if (obj.has("lowPriceVolume") && !obj.get("lowPriceVolume").isJsonNull())
						{
							vol += obj.get("lowPriceVolume").getAsLong();
						}
						if (vol > 0) volume.put(id, vol);
					}
					catch (Exception e)
					{
						log.debug("Skipping item {} in timestamped prices: {}", key, e.getMessage());
					}
				}
				return new PriceAndVolume(prices, volume);
			}
		}
	}

	Map<Integer, ItemMeta> fetchItemMeta(String urlStr) throws IOException
	{
		Request request = new Request.Builder()
				.url(urlStr)
				.header("User-Agent", USER_AGENT)
				.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful() || response.body() == null)
			{
				throw new IOException("Failed to fetch item meta: " + response.code());
			}

			try (Reader reader = response.body().charStream())
			{
				return parseMapping(gson.fromJson(reader, JsonArray.class));
			}
		}
	}

	/** Parse the wiki {@code /mapping} response: an array of {@code {id, name, ...}} objects. */
	static Map<Integer, ItemMeta> parseMapping(JsonArray items)
	{
		Map<Integer, ItemMeta> map = new HashMap<>();
		if (items == null) return map;
		for (JsonElement el : items)
		{
			try
			{
				JsonObject obj = el.getAsJsonObject();
				int id = obj.get("id").getAsInt();
				String name = obj.has("name") && !obj.get("name").isJsonNull()
						? obj.get("name").getAsString() : "Item " + id;
				map.put(id, new ItemMeta(id, name));
			}
			catch (Exception e)
			{
				log.debug("Skipping item in mapping: {}", e.getMessage());
			}
		}
		return map;
	}

	static String makeUrl1h(long now, long offset)
	{
		long ts = now - offset;
		ts -= ts % 3600;
		return "https://prices.runescape.wiki/api/v2/osrs/1h?timestamp=" + ts;
	}

	static String makeUrl24h(long now, long offset)
	{
		long ts = now - offset;
		ts -= ts % 86400;
		return "https://prices.runescape.wiki/api/v2/osrs/24h?timestamp=" + ts;
	}

	// ── Result types ─────────────────────────────────────────────────────────

	static class FetchResult
	{
		final LatestPriceResult latest;
		final PriceAndVolume day;
		final PriceAndVolume week;
		final PriceAndVolume month;
		final PriceAndVolume year;
		final Map<Integer, ItemMeta> itemMeta;

		FetchResult(LatestPriceResult latest,
					PriceAndVolume day, PriceAndVolume week,
					PriceAndVolume month, PriceAndVolume year,
					Map<Integer, ItemMeta> itemMeta)
		{
			this.latest   = latest;
			this.day      = day;
			this.week     = week;
			this.month    = month;
			this.year     = year;
			this.itemMeta = itemMeta;
		}
	}

	static class LatestPriceResult
	{
		final Map<Integer, Long> baseline;
		final Map<Integer, Long> high;
		final Map<Integer, Long> low;

		LatestPriceResult(Map<Integer, Long> baseline, Map<Integer, Long> high, Map<Integer, Long> low)
		{
			this.baseline = baseline;
			this.high     = high;
			this.low      = low;
		}
	}

	static class PriceAndVolume
	{
		final Map<Integer, Long> prices;
		final Map<Integer, Long> volume;

		PriceAndVolume(Map<Integer, Long> prices, Map<Integer, Long> volume)
		{
			this.prices = prices;
			this.volume = volume;
		}
	}
}

package com.flippingmasterminds;

import java.util.function.BiFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Helpers for game widget text, which mixes plain text with {@code <col=...>}-style tags. */
final class TaggedText
{
	private TaggedText()
	{
	}

	/**
	 * Replace matches of {@code pattern} in the text outside tags. The function gets the match
	 * and the raw text following it (tags included), and returns the replacement.
	 */
	static String replace(String raw, Pattern pattern, BiFunction<Matcher, String, String> fn)
	{
		StringBuilder out = new StringBuilder();
		int i = 0;
		while (i < raw.length())
		{
			int tag = raw.indexOf('<', i);
			if (tag == i)
			{
				int close = raw.indexOf('>', i);
				if (close < 0) close = raw.length() - 1;
				out.append(raw, i, close + 1);
				i = close + 1;
				continue;
			}
			int end = tag < 0 ? raw.length() : tag;
			Matcher m = pattern.matcher(raw.substring(i, end));
			StringBuffer sb = new StringBuffer();
			while (m.find())
			{
				String after = raw.substring(i + m.end());
				m.appendReplacement(sb, Matcher.quoteReplacement(fn.apply(m, after)));
			}
			m.appendTail(sb);
			out.append(sb);
			i = end;
		}
		return out.toString();
	}
}

package com.flippingmasterminds;

import org.junit.Test;

