package com.flippingmasterminds;

import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import static org.junit.Assert.*;

public class GEDataSenderTest
{
	private MockWebServer server;
	private OkHttpClient client;
	private ScheduledExecutorService scheduler;
	private GEDataSender sender;

	@Before
	public void setUp() throws IOException
	{
		server = new MockWebServer();
		server.start();
		client = new OkHttpClient();
		scheduler = Executors.newSingleThreadScheduledExecutor();

		String baseUrl = server.url("").toString();
		sender = new GEDataSender(client, scheduler, baseUrl);
		sender.minSendIntervalMs = 10;
		sender.initialBackoffMs = 50;
		sender.maxBackoffMs = 200;
		sender.defaultRetryAfterMs = 100;
	}

	@After
	public void tearDown() throws IOException
	{
		sender.shutdown();
		scheduler.shutdownNow();
		server.shutdown();
	}

	@Test
	public void testSuccessfulDeliverySendsHeadersAndPayload() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(200));

		sender.submit("{\"test\":1}", "token123");

		RecordedRequest request = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("Expected a request to be sent", request);
		assertEquals("/ge", request.getPath());
		assertEquals("Bearer token123", request.getHeader("Authorization"));
		assertEquals(GEDataSender.PLUGIN_VERSION, request.getHeader("X-FM-Plugin-Version"));
		assertEquals("{\"test\":1}", request.getBody().readUtf8());
	}

	@Test
	public void test403StopsSendingUntilTokenChange() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(403));
		server.enqueue(new MockResponse().setResponseCode(200));

		sender.submit("{\"test\":1}", "bad-token");

		RecordedRequest first = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull(first);
		Thread.sleep(100);

		sender.submit("{\"test\":2}", "bad-token");
		Thread.sleep(200);
		assertEquals(1, server.getRequestCount());

		sender.onTokenChanged("new-token");
		sender.submit("{\"test\":3}", "new-token");

		RecordedRequest resumed = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("Expected sending to resume after token change", resumed);
		assertEquals("Bearer new-token", resumed.getHeader("Authorization"));
		assertEquals("{\"test\":3}", resumed.getBody().readUtf8());
	}

	@Test
	public void test401AlsoRejectsToken() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(401));

		sender.submit("{\"test\":1}", "expired-token");

		RecordedRequest first = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull(first);
		Thread.sleep(100);

		sender.submit("{\"test\":2}", "expired-token");
		Thread.sleep(200);
		assertEquals(1, server.getRequestCount());
	}

	@Test
	public void test429HonoursRetryAfter() throws Exception
	{
		server.enqueue(new MockResponse()
				.setResponseCode(429)
				.setHeader("Retry-After", "1"));
		server.enqueue(new MockResponse().setResponseCode(200));

		sender.submit("{\"test\":1}", "token");

		RecordedRequest first = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull(first);

		RecordedRequest retry = server.takeRequest(3, TimeUnit.SECONDS);
		assertNotNull("Expected retry after rate limit", retry);
		assertEquals("{\"test\":1}", retry.getBody().readUtf8());
	}

	@Test
	public void testBackoffGrowsAndResetsOnSuccess() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(500));
		server.enqueue(new MockResponse().setResponseCode(500));
		server.enqueue(new MockResponse().setResponseCode(200));
		server.enqueue(new MockResponse().setResponseCode(200));

		sender.submit("{\"test\":1}", "token");

		RecordedRequest r1 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("First request", r1);

		long beforeFirstRetry = System.currentTimeMillis();
		RecordedRequest r2 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("First retry after 500", r2);
		long firstRetryDelay = System.currentTimeMillis() - beforeFirstRetry;

		long beforeSecondRetry = System.currentTimeMillis();
		RecordedRequest r3 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("Second retry after 500", r3);
		long secondRetryDelay = System.currentTimeMillis() - beforeSecondRetry;

		assertTrue("Second backoff should be longer than first",
				secondRetryDelay >= firstRetryDelay * 0.8);

		sender.submit("{\"test\":2}", "token");

		RecordedRequest r4 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("Request after backoff reset", r4);
	}

	@Test
	public void testCoalescingSendsOnlyLatest() throws Exception
	{
		server.enqueue(new MockResponse()
				.setResponseCode(200)
				.setBodyDelay(300, TimeUnit.MILLISECONDS));
		server.enqueue(new MockResponse().setResponseCode(200));

		sender.submit("{\"v\":1}", "token");

		RecordedRequest first = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull(first);
		assertEquals("{\"v\":1}", first.getBody().readUtf8());

		sender.submit("{\"v\":2}", "token");
		sender.submit("{\"v\":3}", "token");
		sender.submit("{\"v\":4}", "token");

		RecordedRequest second = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull(second);
		assertEquals("{\"v\":4}", second.getBody().readUtf8());

		assertNull("No more requests expected",
				server.takeRequest(300, TimeUnit.MILLISECONDS));
	}

	@Test
	public void testDedupOnlyAfterSuccessfulDelivery() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(500));
		server.enqueue(new MockResponse().setResponseCode(200));

		sender.submit("{\"same\":true}", "token");

		RecordedRequest r1 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull(r1);
		assertEquals("{\"same\":true}", r1.getBody().readUtf8());

		RecordedRequest r2 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("Same payload should retry after failure", r2);
		assertEquals("{\"same\":true}", r2.getBody().readUtf8());

		sender.submit("{\"same\":true}", "token");
		Thread.sleep(200);
		assertEquals("Duplicate payload after successful delivery should be skipped",
				2, server.getRequestCount());
	}

	@Test
	public void test400DropsPayload() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(400));

		sender.submit("{\"bad\":true}", "token");

		RecordedRequest r1 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull(r1);

		Thread.sleep(200);
		assertEquals("400 should drop payload, no retry", 1, server.getRequestCount());
	}

	@Test
	public void testMultipleRejectionCyclesAllResumeAfterTokenChange() throws Exception
	{
		server.enqueue(new MockResponse().setResponseCode(403));
		server.enqueue(new MockResponse().setResponseCode(200));
		server.enqueue(new MockResponse().setResponseCode(403));
		server.enqueue(new MockResponse().setResponseCode(200));

		sender.submit("{\"a\":1}", "bad-token");
		server.takeRequest(2, TimeUnit.SECONDS);
		Thread.sleep(100);

		sender.onTokenChanged("new-token");
		sender.submit("{\"a\":2}", "new-token");
		RecordedRequest r2 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("Should resume after first token change", r2);
		assertEquals("{\"a\":2}", r2.getBody().readUtf8());

		Thread.sleep(100);

		sender.onTokenChanged("another-token");
		sender.submit("{\"a\":3}", "another-token");
		RecordedRequest r3 = server.takeRequest(2, TimeUnit.SECONDS);
		assertNotNull("Should resume after second token change", r3);
		assertEquals("{\"a\":3}", r3.getBody().readUtf8());
	}
}

package com.flippingmasterminds;

import org.junit.Test;

import static org.junit.Assert.*;

public class GeHistoryFilterTest
{
	/** 3 whips at 1.5m each = 4.5m total. */
	private static final GeHistoryEntry WHIPS = new GeHistoryEntry(true, 4151, 3, 4_500_000, 1_500_000, 0);
	/** 1 twisted bow for 1.2b. */
	private static final GeHistoryEntry TBOW = new GeHistoryEntry(false, 20997, 1, 1_200_000_000, 1_200_000_000, 0);
	/** 10k death runes at 180 = 1.8m. */
	private static final GeHistoryEntry RUNES = new GeHistoryEntry(true, 560, 10_000, 1_800_000, 180, 0);

	private static boolean m(String query, GeHistoryEntry e, String name)
	{
		GeHistoryFilter f = GeHistoryFilter.parse(query);
		return f == null || f.matches(e, name);
	}

	@Test
	public void blankQueryIsNoFilter()
	{
		assertNull(GeHistoryFilter.parse(null));
		assertNull(GeHistoryFilter.parse("   "));
	}

	@Test
	public void matchesNameIgnoringCase()
	{
		assertTrue(m("whip", WHIPS, "Abyssal whip"));
		assertTrue(m("ABYSSAL W", WHIPS, "Abyssal whip"));
		assertFalse(m("bow", WHIPS, "Abyssal whip"));
	}

	@Test
	public void comparesTotal()
	{
		assertTrue(m(">100m", TBOW, "Twisted bow"));
		assertFalse(m(">100m", WHIPS, "Abyssal whip"));
		assertTrue(m("<5m", WHIPS, "Abyssal whip"));
		assertTrue(m(">=4.5m", WHIPS, "Abyssal whip"));
		assertFalse(m(">4.5m", WHIPS, "Abyssal whip"));
		assertTrue(m("=1.2b", TBOW, "Twisted bow"));
		assertTrue(m("> 1M", TBOW, "Twisted bow"));
	}

	@Test
	public void comparesEach()
	{
		assertTrue(m("each>1m", WHIPS, "Abyssal whip"));
		assertFalse(m(">2m", RUNES, "Death rune"));
		assertTrue(m("each<200", RUNES, "Death rune"));
		assertTrue(m("per <200", RUNES, "Death rune"));
		assertFalse(m("each>1m", RUNES, "Death rune"));
	}

	@Test
	public void ranges()
	{
		assertTrue(m("1m-5m", WHIPS, "Abyssal whip"));
		assertTrue(m("5m - 1m", RUNES, "Death rune"));
		assertFalse(m("1m-5m", TBOW, "Twisted bow"));
		assertTrue(m("each 100-200", RUNES, "Death rune"));
	}

	@Test
	public void combinesNameAndValues()
	{
		assertTrue(m("whip >1m <5m", WHIPS, "Abyssal whip"));
		assertFalse(m("whip >5m", WHIPS, "Abyssal whip"));
		assertFalse(m("rune >1m", WHIPS, "Abyssal whip"));
		assertTrue(m("death rune >1m", RUNES, "Death rune"));
		assertTrue(m("whip>1m", WHIPS, "Abyssal whip"));
		assertFalse(m("whip>5m", WHIPS, "Abyssal whip"));
	}

	@Test
	public void numbersInsideNamesStayNames()
	{
		GeHistoryEntry pot = new GeHistoryEntry(true, 2434, 1, 9_000, 9_000, 0);
		assertTrue(m("potion(4)", pot, "Prayer potion(4)"));
		assertTrue(m("3rd age", pot, "3rd age platebody"));
		assertFalse(m("3rd age", pot, "Prayer potion(4)"));
	}
}

package com.flippingmasterminds;

import com.google.gson.Gson;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.*;

public class GeHistoryStoreTest
{
	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	private GeHistoryStore store;
	private long clock = 1_000;

	@Before
	public void setUp()
	{
		store = newStore();
		store.ensureAccount(42);
	}

	private GeHistoryStore newStore()
	{
		return new GeHistoryStore(Filepath.Unchecked.getRooted(tmp.getRoot().toPath()), new Gson(), Runnable::run);
	}

	/** Trade with a distinct total so rows are distinguishable. */
	private static GeHistoryEntry t(int id)
	{
		return new GeHistoryEntry(true, id, 1, id * 10L, id * 10L, 0);
	}

	/** Native list (newest first) holding trades hi..lo. */
	private static List<GeHistoryEntry> nativeList(int hi, int lo)
	{
		List<GeHistoryEntry> l = new ArrayList<>();
		for (int i = hi; i >= lo; i--) l.add(t(i));
		return l;
	}

	private static List<Integer> ids(List<GeHistoryEntry> l)
	{
		List<Integer> out = new ArrayList<>();
		for (GeHistoryEntry e : l) out.add(e.itemId);
		return out;
	}

	private GeHistoryStore.SyncResult sync(List<GeHistoryEntry> rows)
	{
		return store.syncNative(rows, 100);
	}

	private List<Integer> archiveIds(List<GeHistoryEntry> rows)
	{
		return ids(sync(rows).archive);
	}

	/** Record a trade made in RuneLite; returns its timestamp. */
	private long live(int id)
	{
		GeHistoryEntry e = t(id);
		e.timestamp = ++clock;
		store.recordLive(e);
		return e.timestamp;
	}

	@Test
	public void firstViewWithNoLiveTradesArchivesNothing()
	{
		assertTrue(archiveIds(nativeList(5, 1)).isEmpty());
	}

	@Test
	public void rowsThatScrollOffAreArchived()
	{
		sync(nativeList(5, 1));
		// Two new trades pushed 1 and 2 off a 5-row list.
		assertEquals(Arrays.asList(2, 1), archiveIds(nativeList(7, 3)));
		assertEquals(Arrays.asList(4, 3, 2, 1), archiveIds(nativeList(9, 5)));
	}

	@Test
	public void reopeningWithoutNewTradesChangesNothing()
	{
		sync(nativeList(5, 1));
		sync(nativeList(7, 3));
		assertEquals(Arrays.asList(2, 1), archiveIds(nativeList(7, 3)));
	}

	@Test
	public void growingListArchivesNothing()
	{
		sync(nativeList(3, 1));
		assertTrue(archiveIds(nativeList(5, 1)).isEmpty());
	}

	@Test
	public void liveTradesFillGapWhenListFullyTurnedOver()
	{
		sync(nativeList(3, 1));
		// Five trades between views; the 3-row list only shows the newest three.
		for (int id = 4; id <= 8; id++) live(id);
		assertEquals(Arrays.asList(5, 4, 3, 2, 1), archiveIds(nativeList(8, 6)));
	}

	@Test
	public void liveTradesBackfillOnFirstView()
	{
		for (int id = 1; id <= 6; id++) live(id);
		assertEquals(Arrays.asList(2, 1), archiveIds(nativeList(6, 3)));
	}

	@Test
	public void repeatedTradesUseLiveCountAsMinimumShift()
	{
		// Same trade repeated: shifts 0, 1 and 2 all line up; two live trades means at least 2.
		sync(Arrays.asList(t(1), t(1), t(1)));
		live(1);
		GeHistoryEntry again = t(1);
		again.timestamp = ++clock;
		store.recordLive(again);
		assertEquals(2, sync(Arrays.asList(t(1), t(1), t(1))).archive.size());
	}

	// ── Trades made outside RuneLite ─────────────────────────────────────────

	@Test
	public void tradesOutsideRuneLiteWithinWindowAreNotLostOrDuplicated()
	{
		sync(nativeList(5, 1));
		live(6);                 // in RuneLite
		// 7 and 8 made on mobile, never recorded live
		assertEquals(Arrays.asList(3, 2, 1), archiveIds(nativeList(8, 4)));
	}

	@Test
	public void mixedTradesAcrossFullTurnoverNeverDuplicate()
	{
		sync(nativeList(3, 1));
		live(4);                 // RuneLite
		// 5 on mobile
		live(6);                 // RuneLite
		// 7 on mobile
		live(8);                 // RuneLite
		// Game now shows 8, 7, 6. Live 8 and 6 are in that list, 4 is older; 5 is unrecoverable.
		assertEquals(Arrays.asList(4, 3, 2, 1), archiveIds(nativeList(8, 6)));
	}

	@Test
	public void firstViewWithOnlyMobileTradesArchivesNothing()
	{
		live(1);
		live(2);
		// Lots of mobile trades since; neither live trade is visible any more, both are older.
		assertEquals(Arrays.asList(2, 1), archiveIds(nativeList(20, 11)));
	}

	// ── Timestamps ───────────────────────────────────────────────────────────

	@Test
	public void nativeRowsGetLiveTimesAndKeepThem()
	{
		sync(nativeList(3, 1));
		long t4 = live(4);
		// 5 on mobile
		long t6 = live(6);

		long[] times = sync(nativeList(6, 2)).nativeTimes;
		assertArrayEquals(new long[]{t6, 0, t4, 0, 0}, times);

		// Next view: those rows have shifted down two places and keep their times.
		live(7);
		live(8);
		times = sync(nativeList(8, 4)).nativeTimes;
		assertEquals(t6, times[2]);
		assertEquals(t4, times[4]);

		// And they keep them once archived.
		for (int id = 9; id <= 13; id++) live(id);
		GeHistoryStore.SyncResult r = sync(nativeList(13, 9));
		assertEquals(Arrays.asList(8, 7, 6, 5, 4, 3, 2, 1), ids(r.archive));
		assertEquals(t6, r.archive.get(2).timestamp);
		assertEquals(0, r.archive.get(3).timestamp);
		assertEquals(t4, r.archive.get(4).timestamp);
	}

	@Test
	public void unmatchedLiveRecordDoesNotArchiveVisibleTrades()
	{
		live(1);
		live(2);
		live(9); // newest, but not (yet) in the game's list
		// Trades 2 and 1 are still visible, so nothing should be archived.
		GeHistoryStore.SyncResult r = sync(nativeList(2, 1));
		assertTrue(r.archive.isEmpty());
		assertTrue(r.nativeTimes[0] > 0 && r.nativeTimes[1] > 0);
	}

	@Test
	public void liveRecordArrivingAfterTheRowStillGetsItsTime()
	{
		sync(nativeList(3, 1));
		// The game adds trade 4 to its list before the plugin has recorded it...
		assertEquals(0, sync(nativeList(4, 1)).nativeTimes[0]);
		// ...then the live record arrives; the next sync fills in the time.
		long t4 = live(4);
		GeHistoryStore.SyncResult r = sync(nativeList(4, 1));
		assertEquals(t4, r.nativeTimes[0]);
		assertTrue(r.archive.isEmpty());
	}

	@Test
	public void formatsAge()
	{
		assertEquals("just now", GeHistoryExtender.formatAge(20_000));
		assertEquals("30m ago", GeHistoryExtender.formatAge(30 * 60_000L));
		assertEquals("21h ago", GeHistoryExtender.formatAge(21 * 3_600_000L + 59 * 60_000L));
		assertEquals("10d ago", GeHistoryExtender.formatAge(10 * 86_400_000L));
		assertEquals("2y ago", GeHistoryExtender.formatAge(800 * 86_400_000L));
	}

	// ── Persistence / formatting ─────────────────────────────────────────────

	@Test
	public void archiveIsCappedAndPersisted()
	{
		sync(nativeList(5, 1));
		sync(nativeList(10, 6));
		assertEquals(Arrays.asList(5, 4, 3), ids(store.syncNative(nativeList(10, 6), 3).archive));

		GeHistoryStore reloaded = newStore();
		reloaded.ensureAccount(42);
		assertEquals(Arrays.asList(5, 4, 3), ids(reloaded.syncNative(nativeList(10, 6), 100).archive));

		GeHistoryStore otherAccount = newStore();
		otherAccount.ensureAccount(7);
		assertTrue(otherAccount.syncNative(nativeList(10, 6), 100).archive.isEmpty());
	}

	@Test
	public void preloadedAccountDataIsUsed()
	{
		sync(nativeList(5, 1));
		sync(nativeList(7, 3));

		GeHistoryStore fresh = newStore();
		fresh.preload(42);
		fresh.ensureAccount(42);
		assertEquals(Arrays.asList(2, 1), ids(fresh.syncNative(nativeList(7, 3), 100).archive));

		// A preload for another account is ignored rather than mixed in.
		GeHistoryStore other = newStore();
		other.preload(42);
		other.ensureAccount(7);
		assertTrue(other.syncNative(nativeList(7, 3), 100).archive.isEmpty());
	}

	@Test
	public void parsesPriceText()
	{
		assertArrayEquals(new long[]{12_345, 12_345},
				GeHistoryExtender.parsePrices("12,345 coins", 1));
		assertArrayEquals(new long[]{1_250, 125},
				GeHistoryExtender.parsePrices("1,250 coins<br><col=ff9040>= 125 each</col>", 10));
		assertArrayEquals(new long[]{1_250, 125},
				GeHistoryExtender.parsePrices("<col=ff9040>= 125 each</col>", 10));
	}

	@Test
	public void rewritesPriceTextKeepingFormatting()
	{
		GeHistoryEntry e = new GeHistoryEntry(false, 1, 4, 2_000_000, 500_000, 0);
		assertEquals("2,000,000 coins<br><col=ff9040>= 500,000 each</col>",
				GeHistoryExtender.rewritePrices("1,250 coins<br><col=ff9040>= 125 each</col>", e));
	}

	@Test
	public void tooltipForBuyComparesAgainstWikiHigh()
	{
		// 21 Oct 2026 14:32 UTC
		long time = java.time.ZonedDateTime.of(2026, 10, 21, 14, 32, 0, 0, java.time.ZoneOffset.UTC)
				.toInstant().toEpochMilli();
		GeHistoryEntry whips = new GeHistoryEntry(true, 4151, 3, 4_500_000, 1_500_000, time);
		assertEquals("Abyssal whip"
						+ "</br>Bought 3 x 1,500,000 ea = 4,500,000"
						+ "</br><col=9f9f9f>21 Oct 2026, 14:32</col>"
						+ "</br>Now: 1,450,000 <col=ff3030>(-3.3%)</col>"
						+ "</br><col=9f9f9f>Wiki buy 1,450,000 / sell 1,440,000</col>",
				GeHistoryExtender.tooltipText(whips, "Abyssal whip", 1_450_000L, 1_440_000L, java.time.ZoneOffset.UTC));
	}

	@Test
	public void tooltipForSaleUsesWikiLowAndHandlesUnknowns()
	{
		GeHistoryEntry bow = new GeHistoryEntry(false, 20997, 1, 1_000_000_000, 1_000_000_000, 0);
		assertEquals("Twisted bow"
						+ "</br>Sold 1 x 1,000,000,000 ea"
						+ "</br><col=9f9f9f>Time unknown</col>"
						+ "</br>Now: 1,100,000,000 <col=00ff00>(+10.0%)</col>"
						+ "</br><col=9f9f9f>Wiki buy - / sell 1,100,000,000</col>",
				GeHistoryExtender.tooltipText(bow, "Twisted bow", null, 1_100_000_000L, java.time.ZoneOffset.UTC));

		// No wiki price at all: just the trade.
		assertEquals("Twisted bow</br>Sold 1 x 1,000,000,000 ea</br><col=9f9f9f>Time unknown</col>",
				GeHistoryExtender.tooltipText(bow, "Twisted bow", null, null, java.time.ZoneOffset.UTC));
	}

	@Test
	public void templatePrefersParityThenSide()
	{
		List<GeHistoryEntry> rows = Arrays.asList(
				new GeHistoryEntry(true, 1, 1, 1, 1, 0),
				new GeHistoryEntry(false, 1, 1, 1, 1, 0),
				new GeHistoryEntry(false, 1, 1, 1, 1, 0),
				new GeHistoryEntry(true, 1, 1, 1, 1, 0));
		GeHistoryEntry sell = new GeHistoryEntry(false, 2, 1, 1, 1, 0);
		// Row 4 is even: rows 0 and 2 qualify, row 2 is a sell.
		assertEquals(2, GeHistoryExtender.pickTemplate(rows, 4, sell));
		// Row 5 is odd: row 1 is the odd sell.
		assertEquals(1, GeHistoryExtender.pickTemplate(rows, 5, sell));
	}
}

package com.flippingmasterminds;

import org.junit.Test;

import static org.junit.Assert.*;

public class GeOfferValueExpanderTest
{
	private static final long[] NONE = {};

	@Test
	public void expandsCondensedCoinValue()
	{
		long[] coins = {130_311_121L};
		assertEquals("130,311,121 coins", GeOfferValueExpander.expand("130.3M coins", coins, NONE));
		assertEquals("130,311,121 coins", GeOfferValueExpander.expand("130.3m coins", coins, NONE));
	}

	@Test
	public void keepsTagsAndOtherText()
	{
		long[] coins = {1_250_000L};
		assertEquals("<col=ffb83f>1,250,000 coins</col>",
				GeOfferValueExpander.expand("<col=ffb83f>1.25M coins</col>", coins, NONE));
		assertEquals("<col=ff9040>12,500</col> coins",
				GeOfferValueExpander.expand("<col=ff9040>12.5K</col> coins", new long[]{12_500}, NONE));
	}

	@Test
	public void picksTheCandidateThatMatches()
	{
		// Price each 4.5M, total 13.5M: "13.5M coins" must become the total.
		long[] coins = {4_500_000L, 13_500_000L, 9_000_000L};
		assertEquals("13,500,000 coins", GeOfferValueExpander.expand("13.5M coins", coins, NONE));
	}

	@Test
	public void leavesTextAloneWhenTheValueIsAmbiguous()
	{
		// Total 130,000,000 and spent 129,950,000 both show as "130M": don't guess.
		long[] coins = {1_000_000L, 130_000_000L, 129_950_000L};
		assertEquals("130M coins", GeOfferValueExpander.expand("130M coins", coins, NONE));
		// Equal candidates (quantity 1: price == total) are not ambiguous.
		assertEquals("2,500,000 coins",
				GeOfferValueExpander.expand("2.5M coins", new long[]{2_500_000L, 2_500_000L, 0}, NONE));
	}

	@Test
	public void leavesTextAloneWhenNothingMatches()
	{
		long[] coins = {999L};
		assertEquals("130.3M coins", GeOfferValueExpander.expand("130.3M coins", coins, NONE));
		assertEquals("1,234 coins", GeOfferValueExpander.expand("1,234 coins", coins, NONE));
		assertEquals("Rune 2h sword", GeOfferValueExpander.expand("Rune 2h sword", coins, new long[]{2}));
	}

	@Test
	public void quantitiesUseQuantityCandidates()
	{
		long[] coins = {1_450L};
		long[] qty = {1_500L, 600L};
		assertEquals("1,500", GeOfferValueExpander.expand("1.5K", coins, qty));
	}

	@Test
	public void matchHandlesRoundingAndTruncation()
	{
		// 130.35M rounds to 130.4M but truncates to 130.3M; both displays map back.
		assertEquals(Long.valueOf(130_350_000L), GeOfferValueExpander.match("130.3", "M", new long[]{130_350_000L}));
		assertEquals(Long.valueOf(130_350_000L), GeOfferValueExpander.match("130.4", "M", new long[]{130_350_000L}));
		assertNull(GeOfferValueExpander.match("130.3", "M", new long[]{130_500_000L}));
		assertEquals(Long.valueOf(2_000_000_000L), GeOfferValueExpander.match("2", "B", new long[]{2_000_000_000L}));
	}
}

package com.flippingmasterminds;

import com.google.gson.Gson;
import org.junit.Test;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.*;

public class PriceAlertTrackerTest
{
	private final Gson gson = new Gson();

	@Test
	public void readsLegacyAlertFormat()
	{
		String legacy = "4151,Abyssal whip,1500000,BELOW,false,0,1000,false,86400000"
				+ "|560,Rune&comma; death &pipe; test,200,ABOVE,true,210,2000,false,3600000";
		List<PriceAlertTracker.PriceAlert> alerts = PriceAlertTracker.parseAlerts(legacy, gson);

		assertEquals(2, alerts.size());
		assertEquals("Abyssal whip", alerts.get(0).itemName);
		assertEquals(PriceAlertTracker.Direction.BELOW, alerts.get(0).direction);
		assertEquals("Rune, death | test", alerts.get(1).itemName);
		assertTrue(alerts.get(1).triggered);
		assertEquals(210, alerts.get(1).triggeredPrice);
		assertEquals(3_600_000, alerts.get(1).expiryMs);
	}

	@Test
	public void alertsRoundTripThroughJson()
	{
		PriceAlertTracker.PriceAlert a = PriceAlertTracker.parseAlerts(
				"4151,Abyssal whip,1500000,ABOVE,true,1600000,1000,false,86400000", gson).get(0);
		String json = gson.toJson(Arrays.asList(a));
		assertTrue(PriceAlertTracker.isJson(json));

		PriceAlertTracker.PriceAlert back = PriceAlertTracker.parseAlerts(json, gson).get(0);
		assertEquals(4151, back.itemId);
		assertEquals("Abyssal whip", back.itemName);
		assertEquals(1_500_000, back.targetPrice);
		assertEquals(PriceAlertTracker.Direction.ABOVE, back.direction);
		assertTrue(back.triggered);
		assertEquals(1_600_000, back.triggeredPrice);
		assertEquals(86_400_000, back.expiryMs);
	}

	@Test
	public void readsLegacyAndJsonHistory()
	{
		String legacy = "4151,Abyssal whip,1500000,BELOW,1000,2000,1490000,TRIGGERED";
		List<PriceAlertTracker.AlertHistoryEntry> h = PriceAlertTracker.parseHistory(legacy, gson);
		assertEquals(1, h.size());
		assertEquals("TRIGGERED", h.get(0).outcome);

		List<PriceAlertTracker.AlertHistoryEntry> back =
				PriceAlertTracker.parseHistory(gson.toJson(h), gson);
		assertEquals(1, back.size());
		assertEquals(1_490_000, back.get(0).triggeredPrice);
		assertEquals(PriceAlertTracker.Direction.BELOW, back.get(0).direction);
	}

	@Test
	public void badInputIsIgnored()
	{
		assertTrue(PriceAlertTracker.parseAlerts(null, gson).isEmpty());
		assertTrue(PriceAlertTracker.parseAlerts("[not json", gson).isEmpty());
		assertTrue(PriceAlertTracker.parseAlerts("garbage|1,2", gson).isEmpty());
		assertTrue(PriceAlertTracker.parseHistory("[{\"itemId\":1}]", gson).isEmpty());
	}
}

package com.flippingmasterminds;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import org.junit.Test;

import java.util.Map;

import static org.junit.Assert.*;

public class PriceDataFetcherTest
{
	@Test
	public void parsesWikiMapping()
	{
		String json = "["
				+ "{\"examine\":\"A weapon from the abyss.\",\"id\":4151,\"members\":true,\"limit\":70,"
				+ "\"value\":120001,\"icon\":\"Abyssal whip.png\",\"name\":\"Abyssal whip\"},"
				+ "{\"id\":560,\"name\":\"Death rune\"},"
				+ "{\"id\":2},"
				+ "{\"name\":\"no id\"}"
				+ "]";
		Map<Integer, ItemMeta> meta = PriceDataFetcher.parseMapping(new Gson().fromJson(json, JsonArray.class));

		assertEquals(3, meta.size());
		assertEquals("Abyssal whip", meta.get(4151).name);
		assertEquals("Death rune", meta.get(560).name);
		assertEquals("Item 2", meta.get(2).name);
	}

	@Test
	public void nullMappingIsEmpty()
	{
		assertTrue(PriceDataFetcher.parseMapping(null).isEmpty());
	}
}
